const DEFAULT_EVENT_IMAGE = 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=1200&q=80';

const CATEGORY_IMAGES = {
  workshop: 'https://images.unsplash.com/photo-1515169067868-5387ec356754?auto=format&fit=crop&w=1200&q=80',
  seminar: 'https://images.unsplash.com/photo-1523580494863-6f3031224c94?auto=format&fit=crop&w=1200&q=80',
  sports: 'https://images.unsplash.com/photo-1521412644187-c49fa049e84d?auto=format&fit=crop&w=1200&q=80',
  music: 'https://images.unsplash.com/photo-1501386761578-eac5c94b800a?auto=format&fit=crop&w=1200&q=80',
  cultural: 'https://images.unsplash.com/photo-1464375117522-1311dd6fa27c?auto=format&fit=crop&w=1200&q=80',
  tech: 'https://images.unsplash.com/photo-1518770660439-4636190af475?auto=format&fit=crop&w=1200&q=80',
  conference: 'https://images.unsplash.com/photo-1475721027785-f74eccf877e2?auto=format&fit=crop&w=1200&q=80',
};

export const getEventImage = (event) => {
  if (event?.imageUrl && event.imageUrl.trim()) {
    return event.imageUrl;
  }

  const key = (event?.category || '').trim().toLowerCase();
  return CATEGORY_IMAGES[key] || DEFAULT_EVENT_IMAGE;
};

export const getSafeFallbackImage = (event) => {
  const key = (event?.category || '').trim().toLowerCase();
  return CATEGORY_IMAGES[key] || DEFAULT_EVENT_IMAGE;
};
